window.YL=window.YL||{};
YL.cards={
 paper:{title:'剪纸：以剪刀代笔',body:'剪纸是用剪刀或刻刀在纸上镂空造型的民间艺术。基本手法分两种：<b>阳刻</b>留线去面，线条相连；<b>阴刻</b>留面去线，块面为主。陕北剪纸多用阴刻阳刻结合，造型夸张、线条粗犷。',more:'2006 年，剪纸被列入第一批国家级非物质文化遗产名录。陕北剪纸是其中极具地域特色的一支，常见于窗花、炕围花、门笺与喜花。'},
 wall:{title:'榆林与明长城',body:'榆林地处陕甘宁蒙交界，明代为边防要地，属「九边重镇」之一的<b>延绥镇</b>。境内明长城遗存绵延千余里，墙体、墩台、营堡相间分布，多用夯土筑成，局部包砖。<p>长城在这里不只是墙，更是一条把农耕与游牧连在一起的分界线。</p>',more:'榆林也因此留下「驼城」的别称——明清时期这里是塞上商贸重镇，商队驼铃不断。'},
 tower:{title:'镇北台：万里长城第一台',body:'镇北台位于榆林城北红山顶，建于明万历三十五年（1607 年），是明长城沿线规模最大的军事瞭望与防御建筑之一，素有「万里长城第一台」之称。<p>台体方正，自下而上逐层收分，共四层，外砌砖石、内夯黄土，台顶原有城楼。它与附近的款贡城、易马城同为明代蒙汉互市、边贸往来的重要场所。</p>',more:'「台」这种形制，是长城防御体系里的瞭望节点：居高望远，烽燧相望，一台举火，全线可知。'},
 battlement:{title:'敌楼',body:'城墙上的方形高台叫<b>敌楼</b>（也称敌台），供士兵瞭望、值守与存放器械。戚继光在蓟镇修边时大量推广这种「空心敌台」，可住人、可储物、可射击。'},
 earth:{title:'夯土墙',body:'榆林一带的长城多为<b>夯土</b>筑成：把黄土层层夯实，就地取材，坚固耐久。只有重要段落和台体才外包砖石。风吹雨打几百年，土墙的层次仍清晰可辨。'}
};
Object.assign(YL.cards,{"shaannorth": {"title": "陕北剪纸", "body": "陕北剪纸是中国民间剪纸的重要分支，造型夸张洗练、线条粗犷有力，题材多是身边的生活：窗花、炕围花、鞋样、喜花、生肖与农事。</p><p>一把剪刀、一张红纸，不打草稿，心里有样子就直接下剪——讲究「以心造型」。", "more": "<p>2006 年，剪纸列入第一批国家级非物质文化遗产名录。陕北剪纸与当地窑洞生活、年节习俗紧紧连在一起：过年贴窗花，嫁娶贴喜花，炕围贴炕围花。</p>"}, "yaodong": {"title": "陕北窑洞", "body": "窑洞是黄土高原的传统民居，利用黄土的直立性<b>靠崖挖筑</b>，常见的有靠崖式、下沉式（地坑院）和独立式（箍窑）。</p><p>厚厚的土层隔热保温，形成「冬暖夏凉」的居住体验，也造就了窑洞特有的拱形门窗与窗棂格。", "more": "<p>门窗是窑洞的「脸」：上部的窗棂通风采光，下部多为实体，拱形结构把受力分散到两侧，是黄土高原上最简洁也最聪明的力学答案。</p>"}, "caveDoor": {"title": "窑洞的门", "body": "窑洞的门洞多做<b>拱形</b>：拱能把上部的土压力顺着弧线传到两侧，比方形更耐压。门上常贴门神、挂门笺，过年时最热闹。"}, "harvest": {"title": "辣椒与玉米串", "body": "陕北干燥少雨，收获的辣椒、玉米挂在檐下自然风干，一串串挂在窑洞外，既是储存，也是院子里最醒目的颜色。"}, "cliffTree": {"title": "崖上的树", "body": "黄土高原植被稀疏，一棵树就是院子的地标。这些年榆林持续开展<b>治沙造林</b>，毛乌素沙地的绿色正在一点点往回长。"}});
Object.assign(YL.cards,{"yangge": {"title": "陕北秧歌", "body": "陕北秧歌是流行于陕北高原的民间集体歌舞，多在春节、庙会「闹社火」时上场。队伍由<b>伞头</b>领头，手持伞（或拂尘）指挥变换队形，众人持扇、帕、伞、绸，随锣鼓走「十字步」。</p><p>场图有「卷席筒」「蛇蜕皮」等名目，一队人走出满场花样。", "more": "<p>秧歌（陕北秧歌）已被列入国家级非物质文化遗产代表性项目名录。它把祭祀、社火与农闲娱乐揉在一起，是陕北最热闹的公共记忆。</p>"}});
Object.assign(YL.cards,{"suonaCulture": {"title": "绥米唢呐", "body": "绥米唢呐指流传于陕西绥德、米脂一带的唢呐艺术，是陕北唢呐的代表，已被列入国家级非物质文化遗产代表性项目名录。</p><p>唢呐由<b>哨片</b>（芦苇制）、<b>芯子</b>、<b>气盘</b>、<b>木杆</b>（开音孔）与<b>铜碗</b>（喇叭口）组成。音色高亢明亮，穿透力极强，婚丧嫁娶、节庆庙会都少不了它。", "more": "<p>陕北唢呐常以「一班」数人合奏：两支唢呐配合，加鼓、锣、镲。曲牌丰富，既有喜庆的「大摆队」，也有沉郁的祭礼曲调，是黄土高原上最响亮的情绪。</p>"}, "reed": {"title": "哨片", "body": "哨片多用芦苇制成，是唢呐的<b>发声源</b>。气息吹动哨片振动，再经芯子传入管身。哨片软硬、厚薄直接决定音色与音准，乐手常自己修哨。"}, "fingerholes": {"title": "木杆与音孔", "body": "唢呐的杆多为木制，前七后一共八个音孔。手指全按为最低音，自下而上依次抬起，音阶逐级升高；配合气息与口型，还能吹出滑音、颤音。"}, "brassBell": {"title": "铜碗", "body": "铜碗即喇叭口，负责<b>扩音与润色</b>。碗口越大、锥度越长，声音越低沉浑厚；碗口小则高亢尖亮。陕北唢呐的铜碗，让声音能翻过两道梁。"}});
