 const ring=A.svg('circle',{cx:187.5,cy:585,r:19,class:'rhythm-ring'},g),dots=score.notes.map(()=>A.svg('circle',{cx:338,cy:585,r:5.5,fill:'#D83A25','pointer-events':'none',opacity:0},g));
