   if(t-lastFlash>180)ring.setAttribute('class','rhythm-ring');label.textContent=`合拍 ${state.hits}/${count} · 错点 ${state.wrong}/${score.maxWrong}`;A.poseDancer(t/540*Math.PI,.3);
