 async edit(scope){this.load();YL.game.skipper=null;YL.$('#page').innerHTML=`<section class="screen collage-editor fade-in"><div class="toolbar">${YL.game.tool('menu','暂停与菜单','menu')}<p class="chapter-label">终章</p>${YL.game.tool('audio','音效开关','audio')}</div><header class="collage-heading"><h1>展开榆林</h1><p>这一幅山河，由你来拼</p></header><label class="roll-title"><span class="sr-only">画卷名字，最多20字</span><input id="roll-name" maxlength="20" value="" placeholder="给画卷起个名字"></label><div class="roll-wrap"><svg id="collage-board" viewBox="0 0 1000 562.5" aria-label="自由拼贴画卷"></svg></div><p id="piece-name" class="piece-name"></p><div id="piece-tools" class="piece-tools"><button data-transform="small" aria-label="缩小选中图案">－</button><button data-transform="large" aria-label="放大选中图案">＋</button><button data-transform="left" aria-label="向左旋转">↶</button><button data-transform="right" aria-label="向右旋转">↷</button><button data-transform="front">置顶</button><button data-transform="delete">移除</button><button id="undo-piece">撤回</button></div><nav class="palette-tabs" aria-label="素材类别"><button data-theme="全部" class="active">全部</button><button data-theme="山河边塞">山河边塞</button><button data-theme="人家纹样">人家纹样</button><button data-theme="民俗声音">民俗声音</button></nav><div class="motif-palette" aria-label="可拼贴素材"></div><p id="collage-status" class="collage-status" role="status" aria-live="polite"></p><div class="collage-actions"><button id="roll-guide" class="roll-guide">拼贴说明</button><button id="finish-roll" class="primary">收好画卷 ›</button></div><p class="draft-note">草稿自动保存 · 每件图案都可自由摆放</p></section>`;
 const name=YL.$('#roll-name');name.value=this.title;scope.event(name,'input',()=>{this.title=name.value.trim().slice(0,20)||'我的榆林画卷';this.save();});YL.$('#menu').onclick=()=>YL.game.menu();YL.game.bindAudio();this.render();
 const palette=theme=>{const box=YL.$('.motif-palette');box.replaceChildren();for(const a of this.library.filter(a=>theme==='全部'||a.theme===theme)){const b=document.createElement('button');b.dataset.add=a.key;b.innerHTML=`<img src="assets/${a.key}.webp?v=20261018-web3" alt=""><span>${a.name}</span>`;scope.event(b,'click',()=>{if(YL.game.paused)return;if(this.items.length>=36){YL.ui.toast('画卷已有36件，先移除或调整图案');return;}this.snapshot();const id=++this.serial,p={id,key:a.key,x:320+(id%4)*115,y:215+(id%3)*68,scale:1,angle:0};this.items.push(this.clamp(p));this.selected=id;this.save();this.render();YL.audio.tap();});box.append(b);}};palette('全部');scope.event(YL.$('.palette-tabs'),'click',e=>{const b=e.target.closest('[data-theme]');if(!b||YL.game.paused)return;document.querySelectorAll('[data-theme]').forEach(n=>n.classList.toggle('active',n===b));palette(b.dataset.theme);});
 let drag=null;const board=YL.$('#collage-board'),point=e=>YL.interact.point(board,e);
 scope.event(board,'pointerdown',e=>{if(YL.game.paused)return;const g=e.target.closest('[data-piece]');if(!g){this.selected=null;this.render();return;}const p=this.items.find(p=>p.id===+g.dataset.piece),q=point(e);this.selected=p.id;this.snapshot();drag={id:p.id,pointer:e.pointerId,dx:q.x-p.x,dy:q.y-p.y};board.setPointerCapture?.(e.pointerId);this.render();e.preventDefault();});
 scope.event(board,'pointermove',e=>{if(!drag||drag.pointer!==e.pointerId||YL.game.paused)return;const p=this.items.find(p=>p.id===drag.id),q=point(e);p.x=q.x-drag.dx;p.y=q.y-drag.dy;this.clamp(p);this.render();e.preventDefault();});
 const release=e=>{if(!drag||drag.pointer!==e.pointerId)return;drag=null;this.save();};scope.event(board,'pointerup',release);scope.event(board,'pointercancel',release);scope.cleanup(()=>{drag=null;this.save();});
 scope.event(board,'keydown',e=>{const g=e.target.closest('[data-piece]');if(!g||YL.game.paused)return;const p=this.items.find(p=>p.id===+g.dataset.piece);if(['Enter',' '].includes(e.key)){e.preventDefault();this.selected=p.id;this.render();return;}const delta={ArrowLeft:[-8,0],ArrowRight:[8,0],ArrowUp:[0,-8],ArrowDown:[0,8]}[e.key];if(delta){e.preventDefault();this.snapshot();this.selected=p.id;p.x+=delta[0];p.y+=delta[1];this.clamp(p);this.save();this.render();YL.$(`[data-piece="${p.id}"]`)?.focus({preventScroll:true});}});
 scope.event(YL.$('#piece-tools'),'click',e=>{const b=e.target.closest('button');if(!b||b.disabled||YL.game.paused)return;if(b.id==='undo-piece'){this.items=JSON.parse(this.history.pop());this.selected=null;}else{const p=this.items.find(p=>p.id===this.selected);if(!p)return;this.snapshot();switch(b.dataset.transform){case'small':p.scale=Math.max(.45,p.scale-.12);break;case'large':p.scale=Math.min(2.1,p.scale+.12);break;case'left':p.angle-=15;break;case'right':p.angle+=15;break;case'front':this.items=this.items.filter(q=>q!==p);this.items.push(p);break;case'delete':this.items=this.items.filter(q=>q!==p);this.selected=null;break;}this.clamp(p);}this.save();this.render();});
 scope.event(YL.$('#roll-guide'),'click',()=>YL.ui.modal({kicker:'自由拼贴',title:'让山河有你的模样',body:'<p>点素材加入画卷，拖到任何喜欢的位置。选中后可缩放、旋转、置顶或移除；同一图案可以重复使用，撤回可找回上一步。</p><p>山河底景已完整展开。再拼入至少6件图案，包含「山河边塞」「人家纹样」「民俗声音」三类故事，就能收好丰富的榆林画卷。位置完全由你决定。</p><p>草稿自动保存在本机，离开后可接着拼。</p>',buttons:[{label:'继续拼贴'}]}));
 await scope.promise(done=>{scope.event(YL.$('#finish-roll'),'click',async()=>{if(YL.game.paused)return;if(!this.assess().ready){await YL.ui.modal({kicker:'再添一点榆林的故事',title:'让画卷更丰富',body:'<p>'+this.status()+'。</p><p>不用按指定位置摆放，挑你喜欢的图案即可。</p>',buttons:[{label:'继续拼贴'}]});return;}this.save();done();});});
 },
 showResult(){this.selected=null;this.busy=false;YL.$('#page').innerHTML=`<section class="screen roll-result fade-in"><div class="toolbar">${YL.game.tool('back','返回章节目录','back')}<p class="chapter-label">纸上陕北</p>${YL.game.tool('audio','音效开关','audio')}</div><header class="collage-heading"><h1>山河，在你纸上</h1><p>一纸一音，遇见榆林。</p></header><h2 id="result-title"></h2><div class="roll-wrap"><svg id="result-board" viewBox="0 0 1000 562.5" aria-label="已完成的榆林画卷"></svg></div><p class="roll-caption">边塞的风、人家的喜、秧歌的红火、唢呐的声<br>都在这幅由你亲手拼成的画卷里。</p><div class="result-actions"><button id="save-roll" class="primary">保存我的画卷</button><button id="share-roll" class="secondary">把榆林分享出去</button><button id="edit-roll" class="edit-roll">继续修改画卷 ›</button></div><p id="export-status" class="export-status" role="status" aria-live="polite">保存后，也可以把图片分享给朋友。</p><div class="result-foot">旅程已完成 · 六章故事，一幅山河</div></section>`;YL.$('#result-title').textContent=this.title;this.draw(YL.$('#result-board'));YL.$('#back').onclick=()=>YL.game.map();YL.game.bindAudio();YL.$('#edit-roll').onclick=()=>YL.game.start(5,true);YL.$('#save-roll').onclick=()=>this.saveImage();YL.$('#share-roll').onclick=()=>this.shareImage();},
