  if(!Number.isInteger(index)||!YL.chapters[index])return;if(index>0&&!YL.store.data.done.includes(index-1)){YL.ui.toast('先完成'+YL.chapters[index-1].name);return;}
  this.leave();const run=this.runId,ch=this.chapter=YL.chapters[index];this.visual={};this.cuts={};this.step=-1;YL.store.data.chapter=index;YL.store.save();
  YL.$('#page').innerHTML=`<section id="game-screen" class="screen game ${ch.scene} fade-in">${YL.art.backdrop(ch.scene)}<div class="toolbar">${this.tool('menu','暂停与菜单','menu')}<div class="toolbar-right">${this.tool('audio','音效开关','audio')}<button class="skip" id="skip">跳过</button></div></div><header class="game-heading"><p class="chapter-label">${ch.no}</p><h1 class="${ch.name.length>5?'long':''}">${ch.name}</h1>${ch.desc?`<p class="game-subtitle">${ch.desc}</p>`:''}</header><div id="narration" class="narration" role="button" tabindex="0" aria-label="点击旁白继续"><p id="narr-text"></p><button id="narr-next" class="next-cue" hidden>轻触继续 ›</button></div><svg id="interactive" class="interactive" viewBox="0 0 375 667" aria-label="${ch.name}互动区域"></svg><div class="hint-area"><p class="instruction" id="instruction"></p><div class="progress-track" id="progress-track" hidden><i id="progress-bar"></i></div><div class="ornament" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="M10 8C2-4 1 8 8 10C-4 18 8 19 10 12C18 24 19 12 12 10C24 2 12 1 10 8Z"/><circle cx="10" cy="10" r="2"/></svg></div></div><div class="knowledge-links" id="knowledge-links" hidden aria-label="文化知识"></div><footer class="game-footer"><button class="primary cta-next" id="stage-next" hidden>继续 ›</button></footer></section>`;
  this.svg=YL.$('#interactive');YL.art.textureDefs(this.svg);if(ch.scene==='sound'){const musician=YL.art.svg('g',{'data-musician':'true'},this.svg);YL.art.image(musician,'musician',YL.art.boxes.musician);}YL.$('#menu').onclick=()=>this.menu();this.bindAudio();YL.$('#skip').onclick=()=>{if(!this.paused&&this.skipper){YL.audio.tap();this.skipper();}};YL.$('#narration').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();YL.$('#narration').click();}};
