Object.assign(YL.cards,{
 'v3-paper':{title:'剪去与留下',body:'剪纸用剪刀或刻刀制作镂空图案。红纸与空白共同组成形象；有阴刻、阳刻、阴阳结合等方式。',more:`<p class="source-links"><a href="${YL.v3.sources.paper}" target="_blank" rel="noopener">中国非遗网 · 中国剪纸</a><a href="${YL.v3.sources.methods}" target="_blank" rel="noopener">技法与用途资料</a></p>`},
 'v3-ansai':{title:'安塞的年节剪纸',body:'安塞剪纸常见于年节和贴窗花的生活。花样表达对生活的愿望，也随创作者变化。这里的叶形与窗口是原创教学示意，不是某位艺人的作品复原。',more:`<p class="source-links"><a href="${YL.v3.sources.ansai}" target="_blank" rel="noopener">中国非遗网 · 安塞剪纸</a></p>`},
 'v3-wall':{title:'榆林红山上的镇北台',body:'镇北台位于榆林红山，与长城及周边遗存共同构成地方历史景观。认识它，既可以看边防，也可以看互市与交流。画面为纸艺综合示意，不是精确实景地图。',more:`<p class="source-links"><a href="${YL.v3.sources.wall2}" target="_blank" rel="noopener">政府网站 · 镇北台资料</a></p>`},
 'v3-market':{title:'边塞与互市',body:'镇北台附近有款贡城、易马城等遗存。它们与边地的官员接待、商洽及互市往来有关，不能把各处场所的作用都归给高台。',more:`<p class="source-links"><a href="${YL.v3.sources.wall}" target="_blank" rel="noopener">榆林市政府资料</a><a href="${YL.v3.sources.wall2}" target="_blank" rel="noopener">交叉参阅</a></p>`},
 'v3-dates':{title:'佳县黄河岸边的枣林',body:'佳县泥河沟村保留着古枣林。枣树既是黄河沿岸的风景，也与当地生产生活相联系。',more:`<p class="source-links"><a href="${YL.v3.sources.dates}" target="_blank" rel="noopener">陕西省政府 · 枣林报道</a></p>`}
});
