  try{await this[index===2?'chapter2':'chapter3'](scope);if(run!==YL.game.runId)return;scope.dispose();YL.game.scope=null;YL.game.skipper=null;YL.store.finish(ch);YL.store.data.folkRevisions={...(YL.store.data.folkRevisions||{}),[index]:index===2?YL.food.version:(YL.waist?.version||this.version)};YL.store.save();this.end(index);}catch(e){if(e.name==='AbortError'||run!==YL.game.runId)return;console.error(e);YL.ui.modal({title:'重新展开这一章',body:'<p>这一段还未完成，可以从本章开头重新体验。</p>',buttons:[{label:'重玩本章',action:()=>YL.game.start(index)},{label:'返回目录',secondary:true,action:()=>YL.game.map()}]});}
