'use strict';
// Chapter two: four easy, single-contour cuts, followed by sourced food stories.
YL.food={
 version:'20261016-food1',
 chapter:{id:2,no:'第二章',name:'灶火人家',subtitle:'一餐一味，认识陕北',gain:'洋芋擦擦·子长煎饼·拼三鲜·子洲馃馅',motif:'flower'},
 topics:['地方来历','食材手艺','入口滋味'],
 dishes:[
  {key:'food-yangyu',name:'洋芋擦擦',place:'陕北多地 · 家常饭食',before:'先从家常饭起剪。洋芋擦擦松松地堆在盘里，盘沿托住细条。沿外缘走一圈，一盘寻常饭食就有了模样。',pages:[
   '洋芋就是土豆。在陕北，常见的土豆与一捧面粉相遇，就能蒸出一笼洋芋擦擦。它既能当饭，也能作菜，讲的是一日三餐里，把普通食材做得有滋味的本事。',
   '用擦子把土豆擦成条，拌匀干面粉，上笼蒸熟。出锅可以浇上盐、醋、辣椒油调成的汁子，也可以搭配青椒、肉丝等再炒，各家有各家的吃法。',
   '蒸好的擦擦绵软，带着薯香与面香。浇汁吃，酸辣衬出清淡的底味；再炒一遍，又多了油香。一盘擦擦，留住了陕北家常饭的实在。'
  ],sources:[['中国作家网 · 洋芋擦擦','https://www.chinawriter.com.cn/n1/2022/1116/c418985-32567496.html'],['陕西年鉴 · 地方饮食','https://dfz.shaanxi.gov.cn/zslm/fzzlk/sxnj/202508/P020250822375845378471.pdf']]},
  {key:'food-jianbing',name:'子长煎饼',place:'延安市 · 子长市',before:'从灶间走到子长的街巷。薄饼卷起豆腐干，两卷相叠，卷口露出馅料。顺着饼身的长弧落剪，留住柔软舒展的形状。',pages:[
   '在子长，煎饼是街巷里的熟悉小吃，也是招待来客的地方滋味。大小饼各有吃法，常见的小饼不过手掌大小。这门制作手艺已列入陕西省级非遗名录。',
   '饼皮主要用荞麦制作。荞麦去壳成糁，加水制浆、过滤，再在铁鏊上摊烙。薄饼可以卷豆腐干、凉菜或肉食，配醋、蒜汁、韭花、辣油等汁料。',
   '饼皮薄而柔韧，豆腐干紧实耐嚼。蘸一口调汁，酸、辣、蒜香与韭花香接连散开。清淡的荞麦皮包住馅料，小小一卷，也有层次。'
  ],sources:[['陕西省艺术馆 · 子长煎饼','https://www.sxfycc.com/home/Index/library_detail.html?id=645'],['人民日报 · 子长煎饼','https://paper.people.com.cn/rmrb/html/2024-11/18/nw.D110000renmrb_20241118_3-20.htm']]},
  {key:'food-sanxian',name:'榆林拼三鲜',place:'榆林市 · 榆阳区',before:'家常饭之外，还有郑重的待客席。剪出这一碗拼三鲜，沿碗口和碗身走一圈，让丰盛的食材留在碗里。',pages:[
   '老榆林的宴席上，拼三鲜是一道郑重待客的大菜，也是传统“老十二件”中的一道。多种食材汇进一碗热汤，显出席面的丰盛，其制作技艺已列入陕西省级非遗名录。',
   '猪、羊、鸡是主要食材，还配丸子、酥肉、粉皮、木耳与蔬菜。煮、炸、蒸等工序分别完成，再合入鲜汤。不同师傅配料有别，一碗菜里藏着几道工夫。',
   '肉片、丸子和酥肉各有口感，粉皮柔滑，木耳与青菜添了清爽。鲜汤把荤素滋味合在一起，醇厚中仍有层次。热腾腾的一碗，是榆林人的待客心意。'
  ],sources:[['陕西省艺术馆 · 拼三鲜','https://www.sxfycc.com/home/Index/library_detail.html?id=537'],['商务部 · 传承与制作','https://lzhbwg.mofcom.gov.cn/edi_ecms_web_front/thb/detail/d5643e6103e846469c1354af1c53c24e']]},
  {key:'food-guoxian',name:'子洲馃馅',place:'榆林市 · 子洲县',before:'最后是一枚子洲馃馅。圆饼微微鼓起，切口露出枣泥与酥层。沿圆润的外缘剪，让这一枚糕点留在纸上。',pages:[
   '在子洲，馃馅既是糕点，也是走亲访友、婚嫁订亲时传递心意的礼食。订亲的馃馅分给亲朋，也把喜讯带到各家。圆鼓的饼形与一点红，寄托团圆、喜庆的愿望。',
   '馃馅讲究酥皮与包馅，常见枣泥、豆沙、五仁等口味。这枚选的是枣泥馅：面皮裹住馅心，整成圆饼，再送入炉中烘烤。饼面的酥层里，有和面与掌火的经验。',
   '先是酥皮的松脆与油香，随后是枣泥的甜润。掰开来看，浅色酥层包着深色馅心，层层分明。一枚馃馅可以是茶点，也承载着当地人馈赠亲友的情意。'
  ],sources:[['陕西日报 · 子洲馃馅','https://www.sxdaily.com.cn/2023-09/19/content_10366820.html'],['榆林日报 · 地方美食','https://www.ylrb.com/2/zt/2023zt/wmdjr/cjdt/961775.shtml']]}
 ],
 box(key){const a=YL.foodArt[key],w=Math.min(309,185*a.width/a.height),h=w*a.height/a.width;return{x:(375-w)/2,y:339+(194-h)/2,w,h};},
 background(){const img=YL.$('#fold-scene');img.className='scene-art scene-food-kitchen';img.src=`assets/v9/food-kitchen.webp?v=20261018-web3`;img.alt='米白留白、黄土墙、灶台与木案组成的陕北灶间纸艺插画';},
 label(title,place){const el=YL.$('#food-label');el.querySelector('h2').textContent=title;el.querySelector('p').textContent=place;},
 clear(){YL.folk.clear();YL.$('#food-topics')?.remove();YL.$('#food-sources')?.remove();},
 gallery(){for(const [i,d]of this.dishes.entries()){const a=YL.foodArt[d.key],w=Math.min(139,88*a.width/a.height),h=w*a.height/a.width;YL.folk.art(d.key,{x:(i%2?201:35)+(139-w)/2,y:(i<2?342:441)+(88-h)/2,w,h});}},
 async read(d,index,scope){
  const nav=document.createElement('nav');nav.id='food-topics';nav.setAttribute('role','tablist');nav.setAttribute('aria-label',d.name+'文化介绍');const buttons=this.topics.map((title,i)=>{const button=document.createElement('button');button.textContent=title;button.type='button';button.id='food-topic-'+i;button.setAttribute('role','tab');button.setAttribute('aria-controls','narr-text');nav.append(button);return button;});YL.$('#game-screen').append(nav);
  const sources=document.createElement('div');sources.id='food-sources';sources.innerHTML=YL.folk.links(d.sources);YL.$('#game-screen').append(sources);YL.$('#narr-text').setAttribute('role','tabpanel');
  let page=0,finished=false;const next=YL.$('#stage-next');next.hidden=false;YL.$('#instruction').textContent='';
  const paint=()=>{YL.game.step=2+index*4+page;YL.$('#narr-text').textContent=d.pages[page];YL.game.lastNarration=d.pages[page];YL.$('#narr-text').setAttribute('aria-labelledby','food-topic-'+page);buttons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===page));b.tabIndex=i===page?0:-1;});YL.$('#fold-footer').textContent=`纸上陕北 · ${index+1} / 4 · ${this.topics[page]}`;next.textContent=page<2?(page===0?'了解食材手艺 ›':'尝一口滋味 ›'):(index===3?'四味齐备 ›':'剪下一道 ›');};paint();
  await scope.promise(resolve=>{const advance=()=>{if(finished||YL.game.paused)return;if(page<2){page++;paint();return;}finished=true;next.hidden=true;next.onclick=null;YL.game.skipper=null;nav.remove();sources.remove();YL.$('#narr-text').removeAttribute('role');YL.$('#narr-text').removeAttribute('aria-labelledby');resolve();};next.onclick=advance;YL.game.skipper=advance;scope.cleanup(()=>{if(next.onclick===advance)next.onclick=null;});buttons.forEach((b,i)=>{scope.event(b,'click',()=>{if(!finished&&!YL.game.paused){page=i;paint();}});scope.event(b,'keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key)||finished||YL.game.paused)return;e.preventDefault();page=e.key==='Home'?0:e.key==='End'?2:(page+(e.key==='ArrowRight'?1:2))%3;paint();buttons[page].focus();});});});
 },
 async run(scope){
  this.background();this.label('灶火里的四种滋味','从家常饭到待客席，再到礼食');this.gallery();YL.folk.stage(0,'灶火人家');await YL.folk.text('窑门里，灶火正旺。家常饭有家常饭的滋味，待客席有待客席的讲究。接下来，用四道简单的轮廓，认识陕北人桌上的饭食与人情。',scope);await YL.v3.continue(scope,'从家常饭起剪 ›');
  for(const [i,d]of this.dishes.entries()){
   this.clear();this.label(d.name,d.place);YL.game.step=1+i*4;YL.$('#fold-footer').textContent=`纸上陕北 · ${i+1} / 4 · 剪出${d.name}`;await YL.folk.text(d.before,scope);const b=this.box(d.key);
   await YL.interact.cut({object:d.key,cutBox:b,resultBox:b,sheetBox:{x:22,y:329,w:331,h:210},hint:'从红点起剪，沿外缘绕一圈；松手可以接着剪',reducedMotion:YL.motion.reduced(),easy:true},scope);
   YL.game.setHint('');await this.read(d,i,scope);
  }
  this.clear();this.label('一桌饭食，几样人情','陕北多地 · 子长 · 榆阳 · 子洲');this.gallery();YL.folk.stage(18,'四味齐备');await YL.folk.text('洋芋擦擦是家常，子长煎饼有街巷的滋味，拼三鲜端上待客席，子洲馃馅把情意送到亲朋手里。饭食里有手艺，也有陕北人的日子。',scope);await YL.v3.continue(scope,'完成第二章 ›');
 },
 end(){YL.ui.modal({kicker:'第二章完成',title:'灶火人家',body:'<p>从洋芋擦擦到子长煎饼，从榆林拼三鲜到子洲馃馅，四种饭食，留下四种地方滋味。</p><p>灶间的热气还未散，院外的腰鼓已经响起来。</p>',close:false,buttons:[{label:'进入第三章',action:()=>YL.game.start(3)},{label:'返回章节目录',secondary:true,action:()=>YL.game.map()}]});}
};
YL.folk.chapters[2]=YL.food.chapter;Object.assign(YL.chapters[2],YL.food.chapter,{desc:YL.food.chapter.subtitle});
const foodShell=YL.folk.shell.bind(YL.folk);YL.folk.shell=function(ch){foodShell(ch);if(ch.id!==2)return;const screen=YL.$('#game-screen');screen.classList.add('food-screen');const label=document.createElement('header');label.id='food-label';label.innerHTML='<h2></h2><p></p>';screen.append(label);YL.food.background();};
YL.folk.chapter2=scope=>YL.food.run(scope);
const foodEnd=YL.folk.end.bind(YL.folk);YL.folk.end=function(index){return index===2?YL.food.end():foodEnd(index);};
const foodImage=YL.art.image.bind(YL.art);YL.art.image=function(parent,key,box,attrs={}){if(!YL.foodArt[key])return foodImage(parent,key,box,attrs);const id='food-art-'+(++YL.folk.serial),defs=this.svg('defs',{},parent),clip=this.svg('clipPath',{id,clipPathUnits:'userSpaceOnUse'},defs);this.svg('path',{d:this.path(key,box)},clip);return this.svg('image',{href:`assets/v9/${key}.webp?v=20261018-web3`,x:box.x,y:box.y,width:box.w,height:box.h,preserveAspectRatio:'none','clip-path':`url(#${id})`,...attrs},parent);};
const foodMap=YL.game.map.bind(YL.game);YL.game.map=async function(){await foodMap();const row=YL.$('[data-chapter="2"]');if(!row)return;row.querySelector('img').src=YL.food.asset?YL.food.asset('food-guoxian'):'assets/v9/food-guoxian.webp?v=20261018-web3';row.querySelector('img').alt=YL.food.chapter.gain;row.querySelector('strong').textContent=YL.food.chapter.name;row.querySelector('small').textContent='第二章 · 陕北四味与地方食俗';if(YL.store.data.done.includes(2))row.querySelector('em').textContent=YL.store.data.folkRevisions?.[2]===YL.food.version?'已完成':'可重剪';};
YL.heritage.end=function(){YL.ui.modal({kicker:'第一章完成',title:'山河与人家',body:'<p>长城、镇北台、统万城遗址、延安宝塔和窑洞，已经留在这一章里。</p><p>接下来推开窑门，走进灶间，认识陕北桌上的四种滋味。</p>',close:false,buttons:[{label:'进入第二章',action:()=>YL.game.start(2)},{label:'返回章节目录',secondary:true,action:()=>YL.game.map()},{label:'重剪第一章',secondary:true,action:()=>YL.game.start(1)}]});};
YL.v3.help=function(){YL.ui.modal({kicker:'纸上陕北',title:'从剪口走进地方生活',body:'<p>序章折剪团花，也可自由设计。第一章沿地图走近陕北遗迹与民居。第二章“灶火人家”依次剪出四种传统美食，认识地方背景、食材手艺与风味。第三章剪出鼓手，跟随真实安塞腰鼓表演录音体验节拍。</p><p>可以松手续剪，也可使用辅助。文化正文下方保留资料链接。音游支持暂停、键盘 F/J 或左右方向键、直接观看及辅助完成。</p><p>进度与作品保存在本机。本次制作到第三章结束，仅供本机预览。</p>',buttons:[{label:'继续体验'}]});};


