YL.tableArt={"food-yangyu":{"width":900,"height":581,"asset":"table-yangyu","guideVertices":28,"concaveTurns":10},"food-jianbing":{"width":900,"height":578,"asset":"table-jianbing","guideVertices":24,"concaveTurns":8},"food-sanxian":{"width":900,"height":588,"asset":"table-sanxian","guideVertices":26,"concaveTurns":7},"food-guoxian":{"width":900,"height":569,"asset":"table-guoxian","guideVertices":28,"concaveTurns":6}};
