C.cut=function(key){const c=YL.store.data.handCuts?.[key]|| (key==='waist-drum'?YL.store.data.waistDrum?.cut:null),p=c?.points;if(!Array.isArray(p)||p.length<3||p.length>2000||!p.every(q=>Array.isArray(q)&&q.length===2&&q.every(Number.isFinite)))return null;return{...c,path:p.map((q,i)=>(i?'L':'M')+q.map(n=>n.toFixed(5)).join(',')).join(' ')+'Z'};};
