C.edit=async function(scope){
 this.load();YL.game.skipper=null;YL.$('#page').innerHTML=`<section class="screen collage-editor shanbei-editor"><div class="toolbar">${YL.game.tool('menu','暂停与菜单','menu')}<p class="chapter-label">终章</p>${YL.game.tool('audio','音效开关','audio')}</div><header class="collage-heading"><h1>展开陕北</h1><p>山河、饭香与鼓乐，都在这一卷里</p></header><label class="roll-title"><span class="sr-only">画卷名称</span><input id="roll-name" maxlength="20" placeholder="给画卷起个名字"></label><div class="roll-wrap"><svg id="collage-board" viewBox="0 0 1000 562.5" aria-label="陕北山河自由画卷"></svg></div><div class="canvas-view-tools"><button id="scroll-all">看全卷</button><button id="scroll-zoom">放大画卷</button></div><p id="piece-name" class="piece-name"></p><div id="piece-tools" class="piece-tools"><button data-transform="small" aria-label="缩小选中图案">－</button><button data-transform="large" aria-label="放大选中图案">＋</button><button data-transform="left" aria-label="向左旋转">↶</button><button data-transform="right" aria-label="向右旋转">↷</button><button data-transform="front">置顶</button><button data-transform="delete">移除</button><button id="undo-piece">撤回</button></div><nav class="palette-tabs" aria-label="素材类别">${['全部','山河往事','窗上花样','民俗声音','陕北四味'].map((t,i)=>`<button data-theme="${t}" class="${i?'':'active'}">${t}</button>`).join('')}</nav><div class="motif-palette" aria-label="前面已剪出或遇见的素材"></div><p id="collage-status" class="collage-status" role="status"></p><div class="collage-actions"><button id="roll-guide" class="roll-guide">拼贴说明</button><button id="finish-roll" class="primary">收好画卷 ›</button></div><p class="draft-note">本机自动存草稿 · 保留前面的剪口和作品</p></section>`;
 const name=YL.$('#roll-name');name.value=this.title;scope.event(name,'input',()=>{this.title=name.value.trim().slice(0,20)||'我的陕北画卷';this.save();});YL.$('#menu').onclick=()=>YL.game.menu();YL.game.bindAudio();this.render();
 const palette=theme=>{const box=YL.$('.motif-palette');box.replaceChildren();for(const a of this.library.filter(a=>this.owned(a)&&(theme==='全部'||a.theme===theme))){const b=document.createElement('button');b.dataset.add=a.key;const icon=YL.art.svg('svg',{viewBox:`0 0 ${a.w} ${a.h}`,'aria-hidden':'true'});YL.prologue.material(icon);this.paint(icon,a,{x:0,y:0,w:a.w,h:a.h});b.append(icon);const label=document.createElement('span');label.textContent=a.name;b.append(label);scope.event(b,'click',()=>{if(YL.game.paused||this.items.length>=36)return;this.snapshot();const id=++this.serial,p=this.clamp({id,key:a.key,x:a.at[0],y:a.at[1],scale:1,angle:0});this.items.push(p);this.selected=id;this.save();this.render();});box.append(b);}};palette('全部');scope.event(YL.$('.palette-tabs'),'click',e=>{const b=e.target.closest('[data-theme]');if(!b||YL.game.paused)return;document.querySelectorAll('[data-theme]').forEach(n=>n.classList.toggle('active',n===b));palette(b.dataset.theme);});scope.event(YL.$('#scroll-all'),'click',()=>this.zoomView(1));scope.event(YL.$('#scroll-zoom'),'click',()=>this.zoomView(YL.scroll.zoom===1?2.2:3));
 const board=YL.$('#collage-board');this.bindView(scope,board);
 scope.event(board,'keydown',e=>{const g=e.target.closest('[data-piece]');if(!g||YL.game.paused)return;const p=this.items.find(p=>p.id===+g.dataset.piece),delta={ArrowLeft:[-8,0],ArrowRight:[8,0],ArrowUp:[0,-8],ArrowDown:[0,8]}[e.key];this.selected=p.id;if(delta){e.preventDefault();this.snapshot();p.x+=delta[0];p.y+=delta[1];this.clamp(p);this.save();this.render();YL.$(`[data-piece="${p.id}"]`)?.focus();}else if(['Enter',' '].includes(e.key)){e.preventDefault();this.render();}});
 scope.event(YL.$('#piece-tools'),'click',e=>{const b=e.target.closest('button');if(!b||b.disabled||YL.game.paused)return;if(b.id==='undo-piece'){this.items=JSON.parse(this.history.pop());this.selected=null;}else{const p=this.items.find(p=>p.id===this.selected);if(!p)return;this.snapshot();switch(b.dataset.transform){case'small':p.scale=Math.max(.45,p.scale-.12);break;case'large':p.scale=Math.min(2.1,p.scale+.12);break;case'left':p.angle-=15;break;case'right':p.angle+=15;break;case'front':this.items=this.items.filter(q=>q!==p);this.items.push(p);break;case'delete':this.items=this.items.filter(q=>q!==p);this.selected=null;break;}this.clamp(p);}this.save();this.render();});
 scope.event(YL.$('#roll-guide'),'click',()=>YL.ui.modal({kicker:'展开陕北',title:'把一路的故事放进山河',body:'<p>画卷从空的山河底景开始，人物和饭菜都由你决定是否加入。下方素材栏保留前面获得的建筑、窗花、带盘饭食，以及鼓手和唢呐乐手。</p><p>点选后可拖动、缩放、旋转、置顶、移除或撤回。素材栏只显示已获得的素材，也能重复加入。双指捏合或鼠标滚轮可围绕手指或光标缩放局部；放大后拖动空地看细节。“看全卷”回到全景。双指缩放不会改变纸片大小。</p><p>不要求凑够指定数量，可以直接收好。这次从空画卷建立独立草稿，之后回来会继续自己的拼贴；此前剪口、自由窗花和旧画卷记录均保留。</p>',buttons:[{label:'继续拼贴'}]}));await scope.promise(done=>scope.event(YL.$('#finish-roll'),'click',()=>{if(!YL.game.paused){this.save();done();}}));
};
C.showResult=function(){this.selected=null;this.busy=false;YL.$('#page').innerHTML=`<section class="screen roll-result"><div class="toolbar">${YL.game.tool('back','返回章节目录','back')}<p class="chapter-label">纸上陕北</p>${YL.game.tool('audio','音效开关','audio')}</div><header class="collage-heading"><h1>展开陕北</h1></header><h2 id="result-title"></h2><div class="roll-wrap"><svg id="result-board" viewBox="0 0 1000 562.5" aria-label="已完成的陕北画卷"></svg></div><div class="canvas-view-tools result-view-tools"><span>双指或滚轮缩放局部</span><button id="result-reset">看全卷</button></div><p class="roll-caption">山河的轮廓、窑院的饭香、鼓声与唢呐<br>都留在这幅亲手拼成的画卷里。</p><div class="result-actions"><button id="save-roll" class="primary">保存我的画卷</button><button id="share-roll" class="secondary">分享陕北画卷</button><button id="return-cover" class="secondary return-cover">完成体验，回到封面</button><button id="edit-roll" class="edit-roll">继续修改画卷 ›</button></div><p id="export-status" class="export-status" role="status">可保存高清图片，留住自己的剪口与摆放。</p></section>`;YL.$('#result-title').textContent=this.title;this.draw(YL.$('#result-board'));YL.scroll.zoom=1;YL.scroll.view={x:0,y:0,w:this.W,h:this.H};const scope=YL.game.scope=new YL.Scope();this.bindView(scope,YL.$('#result-board'),{editable:false});scope.event(YL.$('#result-reset'),'click',()=>this.zoomView(1));YL.$('#back').onclick=()=>YL.game.map();YL.game.bindAudio();YL.$('#edit-roll').onclick=()=>YL.game.start(5,true);YL.$('#save-roll').onclick=()=>this.saveImage();YL.$('#share-roll').onclick=()=>this.shareImage();YL.$('#return-cover').onclick=()=>{if(YL.game.paused||this.busy)return;this.save();YL.store.finish(YL.chapters[5]);YL.game.home();};};
C.exportBlob=async function(){if(this.blob)return this.blob;const before=JSON.stringify(YL.store.data.shanbeiScrollManual),board=YL.art.svg('svg',{xmlns:YL.art.ns,width:1000,height:562.5,viewBox:'0 0 1000 562.5'});this.draw(board,false);const encoded=new Map();await Promise.all([...board.querySelectorAll('image')].map(async node=>{const src=node.getAttribute('href');if(!encoded.has(src))encoded.set(src,fetch(src).then(r=>{if(!r.ok)throw Error('图片素材暂未加载，请重试');return r.blob();}).then(blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);})));node.setAttribute('href',await encoded.get(src));}));const xml=new XMLSerializer().serializeToString(board),svgUrl=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'}));try{const image=await this.image(svgUrl);await Promise.all([document.fonts.load('76px MaShanZheng'),document.fonts.load('28px SourceHanSerif')]);const canvas=document.createElement('canvas');canvas.width=2400;canvas.height=1600;const ctx=canvas.getContext('2d');ctx.fillStyle='#F4EBDD';ctx.fillRect(0,0,2400,1600);ctx.fillStyle='#24221E';ctx.textAlign='center';ctx.font='76px MaShanZheng';ctx.fillText(this.title,1200,120);ctx.font='28px SourceHanSerif';ctx.fillText('纸上陕北 · 山河与日子',1200,179);ctx.drawImage(image,80,230,2240,1260);ctx.strokeStyle='#BC8D4D';ctx.strokeRect(79,229,2242,1262);ctx.fillStyle='#A52B1C';ctx.fillText('亲手剪下的风景，落在自己的画卷里。',1200,1548);const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('图片生成失败，请重试')),'image/png'));if(before===JSON.stringify(YL.store.data.shanbeiScrollManual))this.blob=blob;return blob;}finally{URL.revokeObjectURL(svgUrl);}};
// Keep the existing download/share controls, now consistently named for Shaanbei.
const scrollSaveImage=C.saveImage.bind(C);C.saveImage=async function(){await scrollSaveImage();const m=YL.$('#modal');if(!m?.hidden){const kicker=m.querySelector('.modal-kicker'),image=m.querySelector('.export-preview'),p=m.querySelector('.modal-body p');if(kicker)kicker.textContent='我的陕北画卷';if(image)image.alt='可长按保存的陕北画卷';if(p)p.textContent='手机可长按图片保存，再与朋友分享纸上的陕北。';}};
C.shareImage=async function(){if(this.busy)return;this.busy=true;const run=YL.game.runId,status=YL.$('#export-status');status.textContent='正在准备分享图片…';try{const blob=await this.exportBlob();if(run!==YL.game.runId)return;const file=new File([blob],'纸上陕北.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:this.title,text:'这是我亲手拼成的陕北画卷。'});status.textContent='画卷已准备好分享。';}else{this.busy=false;await this.saveImage();}}catch(e){status.textContent=e.name==='AbortError'?'画卷已保留，可随时再次分享。':'暂时无法直接分享，请保存图片后分享。';}finally{this.busy=false;}};
Object.assign(YL.chapters[5],{name:'展开陕北',desc:'我的陕北画卷',gain:'陕北画卷',end:'山河与日子，都在你亲手展开的画卷里。',steps:[{type:'say',text:'长城、高台与窑院，饭香、鼓声与唢呐，已经走过一程。现在，把这些故事，放回陕北的山河。'},{type:'say',text:'画卷上备好了山梁、河湾和餐桌。用前面亲手剪出的素材，再添上鼓手与乐手，摆出自己的陕北。'},{type:'collage'}]});
const scrollMap=YL.game.map.bind(YL.game);YL.game.map=async function(){await scrollMap();const row=YL.$('[data-chapter="5"]');if(row){row.querySelector('strong').textContent='展开陕北';row.querySelector('small').textContent='终章 · 我的陕北画卷';row.querySelector('img').src=YL.scroll.background;row.querySelector('img').alt='陕北山河画卷';}for(const n of document.querySelectorAll('.chapter-row small'))n.textContent=n.textContent.replace(/\s*·?\s*此前版本/g,'');};
const scrollFolkEnd=YL.folk.end.bind(YL.folk);YL.folk.end=function(index){if(index!==3)return scrollFolkEnd(index);YL.ui.modal({kicker:'第三章完成',title:'一院红火',body:'<p>腰鼓挎到腰间，也跟着安塞腰鼓演出实录，体验了鼓点与动作的呼应。鼓声之后，再去听听陕北的唢呐。</p>',close:false,buttons:[{label:'进入第四章',action:()=>YL.game.start(4)},{label:'返回章节目录',secondary:true,action:()=>YL.game.map()},{label:'再听这段腰鼓',secondary:true,action:()=>YL.ansaiRhythm.revisit()}]});};
YL.v3.help=function(){YL.ui.modal({kicker:'纸上陕北',title:'把故事带回画卷',body:'<p>序章折剪窗花；第一章沿图认识山河往事；第二章剪食物、盛进碗盘；第三章体验安塞腰鼓；第四章保留唢呐流程，聆听传统曲牌《大摆队》实录。终章“展开陕北”从空底景开始，自由选择已经获得的素材拼成画卷。</p><p>文化知识可选阅读，原始资料和录音出处在相应卡片下方。画卷可自由调整、保存高清图片。进度和草稿保存在当前浏览器，可随时继续。</p>',buttons:[{label:'继续体验'}]});};


'use strict';
YL.flow={version:'20261019-result2'};
YL.scroll.version=YL.flow.version;
// Chapters four and five share the same paper-page entrance as the earlier chapters.
const flowStart=YL.game.start.bind(YL.game);
YL.game.start=function(index,edit=false){
 if(![4,5].includes(index)||!YL.store.data.done.includes(index-1))return flowStart(index,edit);
 return YL.motion.navigate(()=>{const run=flowStart(index,edit);YL.$('#page>.screen')?.classList.remove('fade-in');return run;});
};
const flowNarrate=YL.narrate;
YL.narrate=async function(step,scope){
 if(![4,5].includes(YL.game.chapter?.id))return flowNarrate(step,scope);
 const n=YL.$('#narration'),next=YL.$('#narr-next');next.hidden=true;n.onclick=next.onclick=null;YL.game.skipper=null;YL.game.showTags([]);YL.game.setHint('');
 // Fit the entire sentence before entrance, avoiding a typewriter-driven growing box.
 await YL.prologue.text(step.text,scope);
 next.className='next-cue';next.textContent='轻触继续 ›';next.hidden=false;YL.game.showTags(step.tags||[],scope);YL.narrationFit?.fit();
 await scope.promise(done=>{let finished=false;const finish=()=>{if(finished||YL.game.paused)return;finished=true;n.onclick=next.onclick=null;YL.game.skipper=null;done();};n.onclick=finish;next.onclick=e=>{e.stopPropagation();finish();};YL.game.skipper=finish;scope.cleanup(()=>{n.onclick=next.onclick=null;});});
};
const flowEdit=YL.collage.edit.bind(YL.collage);
YL.collage.edit=function(scope){const run=flowEdit(scope);YL.motion.enter();return run;};
const flowResult=YL.collage.showResult.bind(YL.collage);
YL.collage.showResult=function(){flowResult();YL.motion.enter();};


'use strict';
// Cover uses a complete small local subset; story pages keep their original font.
const syncCoverFont=()=>document.body.classList.toggle('font-home',!!YL.$('.v3-cover'));
syncCoverFont();new MutationObserver(syncCoverFont).observe(YL.$('#page'),{childList:true});


'use strict';
YL.narrationFit={
 pending:0,
 fit(){const n=YL.$('#narration'),p=YL.$('#narr-text');if(!n||!p?.firstChild||!YL.$('#game-screen'))return;
  // Include the real first-line indent when measuring the content-aware paper width.
  n.style.width='321px';n.style.removeProperty('--narration-height');const range=document.createRange();range.selectNodeContents(p);const scale=YL.$('#frame').getBoundingClientRect().width/375||1;
  const lines=()=>[...range.getClientRects()].filter(r=>r.width>0&&r.height>0);const rects=lines();if(!rects.length)return;const originalLines=rects.length,style=getComputedStyle(n),padding=['paddingLeft','paddingRight','borderLeftWidth','borderRightWidth'].reduce((s,k)=>s+parseFloat(style[k]||0),0),left=p.getBoundingClientRect().left,longest=Math.max(...rects.map(r=>(r.right-left)/scale)),candidate=Math.max(116,Math.ceil(longest+padding+2));
  if(candidate<321){n.style.width=candidate+'px';if(lines().length>originalLines)n.style.width='321px';}
  // Height comes only from the actual paragraph, optional continue cue and paper padding.
  n.style.height='auto';n.style.minHeight='0';n.dataset.fitted='true';n.dataset.narrationLines=String(lines().length);range.detach();
 },
 schedule(){if(this.pending)return;this.pending=requestAnimationFrame(()=>{this.pending=0;this.fit();});}
};
new MutationObserver(records=>{if(records.some(r=>r.target.id==='page'||r.target.id==='narr-text'||r.target.parentElement?.closest?.('#narr-text')))YL.narrationFit.schedule();}).observe(YL.$('#page'),{childList:true,subtree:true,characterData:true});
window.addEventListener('resize',()=>YL.narrationFit.schedule());document.fonts?.ready.then(()=>YL.narrationFit.schedule());
